"""Independent validation of a plan artifact (does not reuse algo internals)."""
import sys
sys.path.insert(0,'/workspace/submission')
import para, topo


def validate_plan(prof, fabric, plan):
    """Return (ok, message)."""
    cal = para.Calibration(prof)
    if not cal.feasible:
        return (plan.get('status') == 'inconsistent', 'inconsistent shape')
    if plan.get('status') != 'ok':
        return (False, 'status')
    F = topo.Fabric(fabric, cal)
    P, N, T, S = F.P, F.N, F.T, F.S
    if plan.get('period_rounds') != P:
        return (False, 'period')
    # calibration certificate in the plan
    pc = plan.get('profile')
    if not isinstance(pc, dict) or pc.get('status') != 'ok':
        return (False, 'profile status')
    if pc.get('upper_ps') != cal.upper:
        return (False, 'profile upper')
    # peaks
    peaks = plan.get('peaks_as')
    if not isinstance(peaks, list) or len(peaks) != len(F.guards):
        return (False, 'peaks shape')
    gsel = plan.get('guard_ns')
    # recompute the envelope for each guard by brute force (Bellman-Ford)
    def envelope(g):
        bnd=[[None]*N for _ in range(P)]; age=[[0]*N for _ in range(P)]
        for p in range(P):
            for i in F.anchor_nodes[p]: bnd[p][i]=0; age[p][i]=0
        for _ in range(200):
            changed=False
            for p in range(P):
                for i in range(N):
                    if bnd[p][i] is None: continue
                    b,a=bnd[p][i],age[p][i]
                    q=(p+1)%P; nb=b+F.rate[p][i]*T; na=a+1
                    if bnd[q][i] is None or (nb,na)<(bnd[q][i],age[q][i]):
                        bnd[q][i],age[q][i]=nb,na; changed=True
                    rho=F.rho[p]
                    if rho<g: continue
                    for (dst,delta,cost,code,delay) in F.edges[p].get(i,()):
                        if rho+delay+g>S: continue
                        q=(p+delta)%P; nb=b+cost; na=a+delta
                        if bnd[q][dst] is None or (nb,na)<(bnd[q][dst],age[q][dst]):
                            bnd[q][dst],age[q][dst]=nb,na; changed=True
            if not changed: break
        return bnd,age
    for idx,g in enumerate(F.guards):
        bnd,age = envelope(g)
        peak=None
        for p in range(P):
            for i in range(N):
                if bnd[p][i] is None: peak=None; break
                v=bnd[p][i]+F.rate[p][i]*T
                if peak is None or v>peak: peak=v
            if peak is None: break
        if peaks[idx]!=peak: return (False,'peak %d'%idx)
    # the selected guard must be the smallest safe one
    safe=None
    for idx,g in enumerate(F.guards):
        if peaks[idx] is not None and g*1000 >= peaks[idx]+F.reconfig_ns*1000:
            safe=g; break
    if gsel != safe: return (False,'guard selection')
    if safe is None:
        if plan.get('bounds_as') is not None or plan.get('age_rounds') is not None \
           or plan.get('pred') is not None or plan.get('warmup_cycle') is not None:
            return (False,'null matrices expected')
        return (True,'ok (no safe guard)')
    bnd,age = envelope(safe)
    bounds=plan.get('bounds_as'); ages=plan.get('age_rounds'); preds=plan.get('pred')
    for name,mat in (('bounds',bounds),('ages',ages),('preds',preds)):
        if not isinstance(mat,list) or len(mat)!=P: return (False,name+' shape')
        for row in mat:
            if not isinstance(row,list) or len(row)!=N: return (False,name+' row')
    for p in range(P):
        for i in range(N):
            if bounds[p][i]!=bnd[p][i] or ages[p][i]!=age[p][i]:
                return (False,'label mismatch p=%d i=%d'%(p,i))
    # witness validity
    for p in range(P):
        for i in range(N):
            cell=preds[p][i]
            if bounds[p][i] is None:
                if cell is not None: return (False,'null cell has pred')
                continue
            if cell is None:
                if bounds[p][i]!=0 or ages[p][i]!=0: return (False,'anchor cell')
                if i not in F.anchor_nodes[p]: return (False,'anchor cell not anchored')
                continue
            prev,kind=cell
            pp,pi=divmod(prev,N)
            if kind==-1:
                if pi!=i or pp!=(p-1)%P: return (False,'wait step')
                sb=F.rate[pp][i]*T; sa=1
            else:
                lid=kind//2; dr=kind%2
                link=F.links[lid]
                if dr==0: src=link['ends'][0][0]; dst=link['ends'][1][0]; delay=link['delay_ns'][0]; defer=link['defer_rounds'][0]
                else: src=link['ends'][1][0]; dst=link['ends'][0][0]; delay=link['delay_ns'][1]; defer=link['defer_rounds'][1]
                rho=F.rho[pp]
                if lid not in F.slice_set[F.slice_of[pp]]: return (False,'not in slice')
                if rho<safe or rho+delay+safe>S: return (False,'guard')
                if F.blocked(lid,pp,delay): return (False,'blackout')
                x1=rho+delay; delta=(x1+T-1)//T+defer
                if (pp+delta)%P!=p: return (False,'phase')
                if pi!=src or dst!=i: return (False,'endpoints')
                sb=F.allow_by_code[kind]+F.ageing(pp,dst,x1,delta); sa=delta
            if bounds[pp][pi] is None: return (False,'pred unreachable')
            if bounds[p][i]!=bounds[pp][pi]+sb: return (False,'bound equation')
            if ages[p][i]!=ages[pp][pi]+sa: return (False,'age equation')
    # chains terminate at anchors
    for p in range(P):
        for i in range(N):
            if bounds[p][i] is None: continue
            cur=p*N+i; n=0
            while True:
                cell=preds[cur//N][cur%N]
                if cell is None:
                    if bounds[cur//N][cur%N]!=0: return (False,'chain end not anchor')
                    break
                cur=cell[0]; n+=1
                if n>P*N: return (False,'cycle in witness')
    # warmup
    warm=0
    for p in range(P):
        for i in range(N):
            m=(age[p][i]-p+P-1)//P
            if m>warm: warm=m
    if plan.get('warmup_cycle')!=warm: return (False,'warmup')
    return (True,'ok')
PYEOF
